}
.ds-button-dark{
  color: var(--paper);
  background: var(--ink);
  gap: 16px;
  flex-wrap: wrap;
}
.ds-button-dark:hover{
  background: #483949;
}.ds-button{font-family:var(--sans, "Manrope Variable", Arial, sans-serif);cursor:pointer}.ds-button:focus-visible{outline:2px solid var(--gold,#ddc185);outline-offset:6px;}

.ds-text-link{
  display: inline-flex;
  align-items: center;
  gap: 24px;
  border-bottom: 1px solid currentColor;
  padding-bottom: 7px;
  font-size: 12px;
  font-weight: 650;
  transition: gap 0.3s;
}
.ds-text-link:hover{
  gap: 32px;
}.ds-text-link{font-family:var(--sans, "Manrope Variable", Arial, sans-serif);color:var(--gold,#ddc185);text-decoration:none}.ds-text-link:focus-visible{outline:2px solid var(--gold,#ddc185);outline-offset:6px;}

.ds-desktop-nav{
  display: flex;
  gap: 32px;
  font-size: 12px;
  font-weight: 500;
}.ds-desktop-nav{font-family:var(--sans, "Manrope Variable", Arial, sans-serif);color:var(--paper,#f0eeea);background:var(--ink,#252025)}.ds-desktop-nav a{color:inherit;text-decoration:none;transition:color .2s}.ds-desktop-nav a:hover{color:var(--gold,#ddc185)}.ds-desktop-nav a:focus-visible{outline:2px solid var(--gold,#ddc185);outline-offset:6px;}

.ds-lesson-option{
  padding: 34px 34px 10px 0;
  display: flex;
  flex-direction: column;
  position: relative;
  border-right: 1px solid #bfb9bf;
}
.ds-lesson-option h3{
  font-size: 40px;
  line-height: 1.12;
  margin-bottom: 22px;
}
.ds-lesson-option p{
  font-size: 12px;
  line-height: 1.8;
  max-width: 290px;
  margin-bottom: 26px;
}
.ds-option-link{
  display: flex;
  align-items: center;
  gap: 20px;
  font-size: 11px;
  font-weight: 750;
  margin-top: auto;
}
.ds-option-link svg{
  transition: transform 0.3s;
}
.ds-lesson-option:hover .ds-option-link svg{
  transform: translateX(8px);
}
.ds-lesson-option:hover h3{
  color: #77603a;
}
.ds-lesson-option:focus-visible{
  outline-color: var(--ink);
  outline-offset: 4px;
}.ds-lesson-option{font-family:var(--sans, "Manrope Variable", Arial, sans-serif);background:var(--paper,#f0eeea);color:var(--ink,#252025);text-decoration:none}.ds-lesson-option h3{font-family:var(--serif,"Bodoni Moda Variable",Georgia,serif);font-weight:450;letter-spacing:-.025em;margin-top:0}.ds-lesson-option:focus-visible{outline:2px solid var(--gold,#ddc185);outline-offset:6px;}

.ds-watch-trigger{
  position: relative;


  display: flex;
  align-items: center;
  gap: 16px;
  border: 0;
  background: #191719d9;
  padding: 10px 17px 10px 10px;
  text-align: left;
  font-size: 12px;
  font-weight: 650;
  transition: background 0.25s;
}
.ds-watch-trigger:hover{
  background: var(--ink);
}
.ds-play-disc{
  width: 52px;
  height: 52px;
  border: 1px solid #d7c99c;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--gold);
  transition:
    background 0.25s,
    color 0.25s;
}
.ds-watch-trigger:hover .ds-play-disc{
  background: var(--gold);
  color: var(--ink);
}
.ds-watch-trigger small{
  display: block;
  color: #c2b9b9;
  font-size: 10px;
  font-weight: 400;
  margin-top: 4px;
}.ds-watch-trigger{font-family:var(--sans, "Manrope Variable", Arial, sans-serif);color:var(--paper,#f0eeea);cursor:pointer}.ds-watch-trigger:focus-visible{outline:2px solid var(--gold,#ddc185);outline-offset:6px;}

.ds-faq-list{
  border-top: 1px solid #bfb9bf;
}
.ds-faq-list details{
  border-bottom: 1px solid #bfb9bf;
}
.ds-faq-list summary{
  padding: 24px 0;
  list-style: none;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  font-size: 13px;
  font-weight: 650;
}
.ds-faq-list summary::-webkit-details-marker{
  display: none;
}
.ds-faq-list summary svg{
  transition: transform 0.3s;
}
.ds-faq-list details[open] summary svg{
  transform: rotate(45deg);
}
.ds-faq-list details p{
  padding: 0 40px 25px 0;
  font-size: 12px;
  line-height: 1.85;
  color: #5b505a;
  max-width: 600px;
}.ds-faq-list{font-family:var(--sans, "Manrope Variable", Arial, sans-serif);background:var(--paper,#f0eeea);color:var(--ink,#252025)}.ds-faq-list summary{cursor:pointer}.ds-faq-list summary:focus-visible{outline:2px solid #77603a;outline-offset:6px}
